import{_ as p,a0 as l,w as o,s as h,I as a,x as n,a1 as t,A as i,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"使用 C 优化你的 Python 代码 | LCTT x X-CMD","titleTemplate":false,"description":"使用 C 优化你的 Python 代码 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 C 优化你的 Python 代码 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 C 优化你的 Python 代码 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20210421 Optimize your Python code with C","title":"使用 C 优化你的 Python 代码","tag":"202104","desc":""},"relativePath":"202104/20210421 Optimize your Python code with C.md","filePath":"[post].md"}'),d={name:"202104/20210421 Optimize your Python code with C.md"};function c(g,s,u,y,b,k){const e=l("Link");return o(),h("div",null,[s[18]||(s[18]=a("h1",{id:"使用-c-优化你的-python-代码",tabindex:"-1"},[n("使用 C 优化你的 Python 代码 "),a("a",{class:"header-anchor",href:"#使用-c-优化你的-python-代码","aria-label":"Permalink to “使用 C 优化你的 Python 代码”"},"​")],-1)),s[19]||(s[19]=a("blockquote",null,[a("p",null,"Cython 创建的 C 模块可以加速 Python 代码的执行，这对使用效率不高的解释型语言编写的复杂应用是很重要的。")],-1)),s[20]||(s[20]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/26/230709qz64z4af3t9b9jab.jpg",alt:""})],-1)),a("p",null,[s[1]||(s[1]=n("Cython 是 Python 编程语言的编译器，旨在优化性能并形成一个扩展的 Cython 编程语言。作为 Python 的扩展，",-1)),t(e,{href:"https://cython.org/"},{default:i(()=>[...s[0]||(s[0]=[n("Cython",-1)])]),_:1}),s[2]||(s[2]=n(" 也是 Python 语言的超集，它支持调用 C 函数和在变量和类属性上声明 C 类型。这使得包装外部 C 库、将 C 嵌入现有应用程序或者为 Python 编写像 Python 一样简单的 C 语言扩展语法变得容易。",-1))]),s[21]||(s[21]=r(`<p>Cython 一般用于创建 C 模块来加速 Python 代码的执行。这在使用解释型语言编写的效率不高的复杂应用中非常重要。</p><h3 id="安装-cython" tabindex="-1">安装 Cython <a class="header-anchor" href="#安装-cython" aria-label="Permalink to “安装 Cython”">​</a></h3><p>你可以在 Linux、BSD、Windows 或 macOS 上安装 Cython 来使用 Python：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python -m pip install Cython</span></span></code></pre></div><p>安装好后，就可以使用它了。</p><h3 id="将-python-转换成-c" tabindex="-1">将 Python 转换成 C <a class="header-anchor" href="#将-python-转换成-c" aria-label="Permalink to “将 Python 转换成 C”">​</a></h3><p>使用 Cython 的一个好的方式是从一个简单的 “hello world” 开始。这虽然不是展示 Cython 优点的最好方式，但是它展示了使用 Cython 时发生的情况。</p><p>首先，创建一个简单的 Python 脚本，文件命名为 <code>hello.pyx</code>（<code>.pyx</code> 扩展名并不神奇，从技术上它可以是任何东西，但它是 Cython 的默认扩展名）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>print(&quot;hello world&quot;)</span></span></code></pre></div><p>接下来，创建一个 Python 设置脚本。一个像 Python 的 makefile 一样的 <code>setup.py</code>，Cython 可以使用它来处理你的 Python 代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from setuptools import setup</span></span>
<span class="line"><span>from Cython.Build import cythonize</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setup(</span></span>
<span class="line"><span>    ext_modules = cythonize(&quot;hello.pyx&quot;)</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>最后，使用 Cython 将你的 Python 脚本转换为 C 代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python setup.py build_ext --inplace</span></span></code></pre></div><p>你可以在你的工程目录中看到结果。Cython 的 <code>cythonize</code> 模块将 <code>hello.pyx</code> 转换成一个 <code>hello.c</code> 文件和一个 <code>.so</code> 库。这些 C 代码有 2648 行，所以它比一个一行的 <code>hello.pyx</code> 源码的文本要多很多。<code>.so</code> 库也比它的源码大 2000 倍（即 54000 字节和 20 字节相比）。然后，Python 需要运行单个 Python 脚本，所以有很多代码支持这个只有一行的 <code>hello.pyx</code> 文件。</p><p>要使用 Python 的 “hello world” 脚本的 C 代码版本，请打开一个 Python 提示符并导入你创建的新 <code>hello</code> 模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import hello</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><h3 id="将-c-代码集成到-python-中" tabindex="-1">将 C 代码集成到 Python 中 <a class="header-anchor" href="#将-c-代码集成到-python-中" aria-label="Permalink to “将 C 代码集成到 Python 中”">​</a></h3><p>测试计算能力的一个很好的通用测试是计算质数。质数是一个比 1 大的正数，且它只有被 1 或它自己除后才会产生正整数。虽然理论很简单，但是随着数的变大，计算需求也会增加。在纯 Python 中，可以用 10 行以内的代码完成质数的计算。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>number = int(sys.argv[1])</span></span>
<span class="line"><span>if not number &lt;= 1:</span></span>
<span class="line"><span>    for i in range(2, number):</span></span>
<span class="line"><span>        if (number % i) == 0:</span></span>
<span class="line"><span>            print(&quot;Not prime&quot;)</span></span>
<span class="line"><span>            break</span></span>
<span class="line"><span>else:</span></span>
<span class="line"><span>    print(&quot;Integer must be greater than 1&quot;)</span></span></code></pre></div><p>这个脚本在成功的时候是不会提醒的，如果这个数不是质数，则返回一条信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./prime.py 3</span></span>
<span class="line"><span>$ ./prime.py 4</span></span>
<span class="line"><span>Not prime.</span></span></code></pre></div><p>将这些转换为 Cython 需要一些工作，一部分是为了使代码适合用作库，另一部分是为了提高性能。</p><h4 id="脚本和库" tabindex="-1">脚本和库 <a class="header-anchor" href="#脚本和库" aria-label="Permalink to “脚本和库”">​</a></h4><p>许多用户将 Python 当作一种脚本语言来学习：你告诉 Python 想让它执行的步骤，然后它来做。随着你对 Python（以及一般的开源编程）的了解越多，你可以了解到许多强大的代码都存在于其他应用程序可以利用的库中。你的代码越 <em>不具有针对性</em>，程序员（包括你）就越可能将其重用于其他的应用程序。将计算和工作流解耦可能需要更多的工作，但最终这通常是值得的。</p><p>在这个简单的质数计算的例子中，将其转换成 Cython，首先是一个设置脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from setuptools import setup</span></span>
<span class="line"><span>from Cython.Build import cythonize</span></span>
<span class="line"><span></span></span>
<span class="line"><span>setup(</span></span>
<span class="line"><span>    ext_modules = cythonize(&quot;prime.py&quot;)</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>将你的脚本转换成 C：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python setup.py build_ext --inplace</span></span></code></pre></div><p>到目前为止，一切似乎都工作的很好，但是当你试图导入并使用新模块时，你会看到一个错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import prime</span></span>
<span class="line"><span>Traceback (most recent call last):</span></span>
<span class="line"><span>  File &quot;&lt;stdin&gt;&quot;, line 1, in &lt;module&gt;</span></span>
<span class="line"><span>  File &quot;prime.py&quot;, line 2, in init prime</span></span>
<span class="line"><span>    number = sys.argv[1]</span></span>
<span class="line"><span>IndexError: list index out of range</span></span></code></pre></div><p>这个问题是 Python 脚本希望从一个终端运行，其中参数（在这个例子中是要测试是否为质数的整数）是一样的。你需要修改你的脚本，使它可以作为一个库来使用。</p><h4 id="写一个库" tabindex="-1">写一个库 <a class="header-anchor" href="#写一个库" aria-label="Permalink to “写一个库”">​</a></h4><p>库不使用系统参数，而是接受其他代码的参数。对于用户输入，与其使用 <code>sys.argv</code>，不如将你的代码封装成一个函数来接收一个叫 <code>number</code>（或者 <code>num</code>，或者任何你喜欢的变量名）的参数：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def calculate(number):</span></span>
<span class="line"><span>    if not number &lt;= 1:</span></span>
<span class="line"><span>        for i in range(2, number):</span></span>
<span class="line"><span>            if (number % i) == 0:</span></span>
<span class="line"><span>                print(&quot;Not prime&quot;)</span></span>
<span class="line"><span>                break</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;Integer must be greater than 1&quot;)</span></span></code></pre></div><p>这确实使你的脚本有些难以测试，因为当你在 Python 中运行代码时，<code>calculate</code> 函数永远不会被执行。但是，Python 编程人员已经为这个问题设计了一个通用、还算直观的解决方案。当 Python 解释器执行一个 Python 脚本时，有一个叫 <code>__name__</code> 的特殊变量，这个变量被设置为 <code>__main__</code>，但是当它被作为模块导入的时候，<code>__name__</code> 被设置为模块的名字。利用这点，你可以写一个既是 Python 模块又是有效 Python 脚本的库：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import sys</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def calculate(number):</span></span>
<span class="line"><span>    if not number &lt;= 1:</span></span>
<span class="line"><span>        for i in range(2, number):</span></span>
<span class="line"><span>            if (number % i) == 0:</span></span>
<span class="line"><span>                print(&quot;Not prime&quot;)</span></span>
<span class="line"><span>                break</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;Integer must be greater than 1&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>    number = sys.argv[1]    </span></span>
<span class="line"><span>    calculate( int(number) )</span></span></code></pre></div><p>现在你可以用一个命令来运行代码了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python ./prime.py 4</span></span>
<span class="line"><span>Not a prime</span></span></code></pre></div><p>你可以将它转换为 Cython 来用作一个模块：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; import prime</span></span>
<span class="line"><span>&gt;&gt;&gt; prime.calculate(4)</span></span>
<span class="line"><span>Not prime</span></span></code></pre></div><h3 id="c-python" tabindex="-1">C Python <a class="header-anchor" href="#c-python" aria-label="Permalink to “C Python”">​</a></h3><p>用 Cython 将纯 Python 的代码转换为 C 代码是有用的。这篇文章描述了如何做，然而，Cython 还有功能可以帮助你在转换之前优化你的代码，分析你的代码来找到 Cython 什么时候与 C 进行交互，以及更多。如果你正在用 Python，但是你希望用 C 代码改进你的代码，或者进一步理解库是如何提供比脚本更好的扩展性的，或者你只是好奇 Python 和 C 是如何协作的，那么就开始使用 Cython 吧。</p><hr>`,43)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),t(e,{href:"https://opensource.com/article/21/4/cython"},{default:i(()=>[...s[3]||(s[3]=[n("https://opensource.com/article/21/4/cython",-1)])]),_:1})]),a("p",null,[s[9]||(s[9]=n("作者：",-1)),t(e,{href:"https://opensource.com/users/alansmithee"},{default:i(()=>[...s[5]||(s[5]=[n("Alan Smithee",-1)])]),_:1}),s[10]||(s[10]=n(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[n("lujun9972",-1)])]),_:1}),s[11]||(s[11]=n(" 译者：",-1)),t(e,{href:"https://github.com/ShuyRoy"},{default:i(()=>[...s[7]||(s[7]=[n("ShuyRoy",-1)])]),_:1}),s[12]||(s[12]=n(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=n("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[n("LCTT",-1)])]),_:1}),s[16]||(s[16]=n(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[n("Linux中国",-1)])]),_:1}),s[17]||(s[17]=n(" 荣誉推出",-1))])])}const P=p(d,[["render",c]]);export{f as __pageData,P as default};
